all_original_proposals.original_declaration:
thing HousekeepingHousehold
    "An identifiable living arrangement of one person or people living together who make common provision for food and other essentials."
    ;

structural directed relationship HouseholdMembership
    "A person's membership in an identified household under an explicit membership convention."
    links society:HumanIndividual to society:HousekeepingHousehold;

quantity HouseholdSize
    "The number of persons belonging to an identified housekeeping household at the observation reference."
    is imod:Numerosity of society:HousekeepingHousehold;

structural directed relationship OrganizationMembership
    "An agent's recognized membership in an organization under that organization's membership criteria."
    links imod:Agent to society:Organization;

